/// Handle all computer_* MCP tool calls.
///
/// These tools provide Computer Use capabilities to sub-agents via MCP.
/// They route commands through the orchestrator's global session registry
/// for action execution, or return structured commands for the orchestrator.
async fn handle_computer_use_tool(tool_name: &str, args: &Value) -> Value {
    // Check for active sessions
    let sessions = duduclaw_gateway::computer_use_orchestrator::list_sessions().await;
    let active = !sessions.is_empty();

    match tool_name {
        "computer_screenshot" => {
            let display = args
                .get("display")
                .and_then(|v| v.as_str())
                .unwrap_or("container");
            tool_text(&serde_json::json!({
                "action": "screenshot",
                "display": display,
                "active_sessions": sessions,
                "status": if active { "executing" } else { "no_active_session" },
            }).to_string())
        }
        "computer_click" => {
            let x = args.get("x").and_then(|v| v.as_u64()).unwrap_or(0);
            let y = args.get("y").and_then(|v| v.as_u64()).unwrap_or(0);
            let button = args.get("button").and_then(|v| v.as_str()).unwrap_or("left");
            let double = args.get("double").and_then(|v| v.as_bool()).unwrap_or(false);
            let action_name = match (button, double) {
                ("right", _) => "right_click",
                (_, true) => "double_click",
                _ => "left_click",
            };
            tool_text(&serde_json::json!({
                "action": action_name,
                "coordinate": [x, y],
                "status": if active { "executing" } else { "no_active_session" },
            }).to_string())
        }
        "computer_type" => {
            let text = args.get("text").and_then(|v| v.as_str()).unwrap_or("");
            tool_text(&serde_json::json!({
                "action": "type",
                "text": text,
                "status": if active { "executing" } else { "no_active_session" },
            }).to_string())
        }
        "computer_key" => {
            let key = args.get("key").and_then(|v| v.as_str()).unwrap_or("");
            tool_text(&serde_json::json!({
                "action": "key",
                "text": key,
                "status": if active { "executing" } else { "no_active_session" },
            }).to_string())
        }
        "computer_scroll" => {
            let x = args.get("x").and_then(|v| v.as_u64()).unwrap_or(0);
            let y = args.get("y").and_then(|v| v.as_u64()).unwrap_or(0);
            let direction = args.get("direction").and_then(|v| v.as_str()).unwrap_or("down");
            let amount = args.get("amount").and_then(|v| v.as_u64()).unwrap_or(3);
            tool_text(&serde_json::json!({
                "action": "scroll",
                "coordinate": [x, y],
                "direction": direction,
                "amount": amount,
                "status": if active { "executing" } else { "no_active_session" },
            }).to_string())
        }
        "computer_session_start" => {
            let task = args.get("task").and_then(|v| v.as_str()).unwrap_or("Computer use session");
            let width = args.get("width").and_then(|v| v.as_u64()).unwrap_or(1280);
            let height = args.get("height").and_then(|v| v.as_u64()).unwrap_or(800);
            let session_id = uuid::Uuid::new_v4().to_string();
            tool_text(&serde_json::json!({
                "session_id": session_id,
                "task": task,
                "display": format!("{width}x{height}"),
                "status": "started",
                "active_sessions": sessions.len() + 1,
            }).to_string())
        }
        "computer_session_stop" => {
            let session_id = args.get("session_id").and_then(|v| v.as_str()).unwrap_or("");
            // Stop via the session registry
            if let Some(control) = duduclaw_gateway::computer_use_orchestrator::get_session_control(session_id).await {
                control.stopped.store(true, std::sync::atomic::Ordering::Release);
                // NOTE: Do NOT call unregister_session() here — the run_loop in
                // channel_reply.rs is the sole owner of session lifecycle cleanup.
                // Setting stopped=true causes run_loop to exit, which then calls
                // unregister_session(). Calling it here too would create a race.
                tool_text(&serde_json::json!({
                    "session_id": session_id,
                    "status": "stopping",
                    "note": "Stop signal sent. Session will be cleaned up when the orchestrator loop exits.",
                }).to_string())
            } else {
                tool_text(&serde_json::json!({
                    "session_id": session_id,
                    "status": "not_found",
                    "active_sessions": sessions,
                }).to_string())
            }
        }
        _ => tool_error(&format!("Unknown computer use tool: {tool_name}")),
    }
}

// ─────────────────────────────────────────────────────────────────
// Google Workspace native tool handlers (Gmail + Calendar).
//
// These consume the OAuth vault token via the gateway `google_workspace`
// module. The google:read / google:write scope gates are enforced upstream in
// mcp_dispatch; auth/API failures degrade to clear tool_error text that guides
// the user back to the dashboard Integrations → Google page.
// ─────────────────────────────────────────────────────────────────

/// Read a u32 argument that may arrive as a JSON number or string.
fn arg_u32(args: &Value, key: &str, default: u32) -> u32 {
    args.get(key)
        .and_then(|v| v.as_u64())
        .map(|n| n as u32)
        .or_else(|| {
            args.get(key)
                .and_then(|v| v.as_str())
                .and_then(|s| s.trim().parse::<u32>().ok())
        })
        .unwrap_or(default)
}

async fn handle_google_status(home_dir: &Path) -> Value {
    use duduclaw_gateway::google_workspace::{
        GOOGLE_PROVIDER, GoogleBackend, REQUIRED_SCOPES, resolve_backend,
    };
    use duduclaw_gateway::mcp_oauth;

    let token = mcp_oauth::load_tokens(home_dir)
        .into_iter()
        .find(|t| t.provider_id == GOOGLE_PROVIDER);
    let configured = mcp_oauth::has_client_config(home_dir, GOOGLE_PROVIDER);

    let mut out = String::new();

    // Lead with the credential source actually in effect. Three exist (OAuth
    // vault, service-account delegation, Apps Script bridge) and the OAuth
    // detail below only describes the first — without this line a customer on
    // delegation or the bridge reads "NOT connected" while their tools work.
    match resolve_backend(home_dir).await {
        Ok(GoogleBackend::Direct(_)) => {
            out.push_str("Credential source: direct API token (OAuth vault or service-account delegation). All 19 tools available.\n\n");
        }
        Ok(GoogleBackend::AppsScript(cfg)) => {
            out.push_str(&format!(
                "Credential source: {}. Gmail / Calendar / Sheets are available; Drive, Docs, Slides, Forms and Tasks need OAuth or a service account.\n\n",
                cfg.describe()
            ));
        }
        Err(e) => {
            out.push_str(&format!("Credential source: none usable — {e}\n\n"));
        }
    }
    match token {
        None => {
            out.push_str("Google Workspace: NOT connected.\n");
            if configured {
                out.push_str(
                    "Client credentials are set. Open the dashboard Integrations → Google page and click \"Connect Google\" to authorize.",
                );
            } else {
                out.push_str(
                    "No OAuth client is configured. Open the dashboard Integrations → Google page to set up your Google OAuth client, then connect.",
                );
            }
        }
        Some(t) => {
            let now = chrono::Utc::now();
            let (state, expiry) = match t.expires_at {
                Some(exp) if now >= exp => ("EXPIRED".to_string(), exp.to_rfc3339()),
                Some(exp) => ("valid".to_string(), exp.to_rfc3339()),
                None => ("valid (no expiry)".to_string(), "n/a".to_string()),
            };
            let has_refresh = t
                .refresh_token
                .as_deref()
                .map(|s| !s.is_empty())
                .unwrap_or(false);
            let auto_refresh = if has_refresh && configured {
                "available"
            } else {
                "unavailable — reconnect to enable automatic refresh"
            };
            out.push_str(&format!(
                "Google Workspace: connected.\nToken: {state} (expires: {expiry})\nAuto-refresh: {auto_refresh}\nGranted scopes:\n"
            ));
            for s in &t.scopes {
                out.push_str(&format!("  - {s}\n"));
            }
            let missing: Vec<&str> = REQUIRED_SCOPES
                .iter()
                .copied()
                .filter(|req| !t.scopes.iter().any(|s| s == req))
                .collect();
            if !missing.is_empty() {
                out.push_str(
                    "\nMissing scopes needed for full Gmail/Calendar functionality (reconnect from the dashboard to grant):\n",
                );
                for m in missing {
                    out.push_str(&format!("  - {m}\n"));
                }
            }
        }
    }
    tool_text(out.trim_end())
}

async fn handle_gmail_search(args: &Value, home_dir: &Path) -> Value {
    use duduclaw_gateway::google_workspace as gw;

    let query = match args.get("query").and_then(|v| v.as_str()) {
        Some(q) if !q.trim().is_empty() => q,
        _ => return tool_error("Missing required parameter: query"),
    };
    let max = arg_u32(args, "max_results", 10);

    let backend = match gw::resolve_backend(home_dir).await {
        Ok(b) => b,
        Err(e) => return tool_error(&e.to_string()),
    };
    match gw::gmail_search_via(&backend, query, max).await {
        Ok(r) => tool_text(&serde_json::to_string_pretty(&r).unwrap_or_default()),
        Err(e) => tool_error(&e.to_string()),
    }
}

