        let result = spawn_agent_with_ctx(&params, home, "main", ctx).await;

        assert_eq!(result["isError"].as_bool(), Some(true), "archived spawn must fail: {result}");
        let text = result["content"][0]["text"].as_str().unwrap_or("");
