        let params = serde_json::json!({
            "instruction": "x", "context": "y", "tools": ["Read"],
        });
        let ctx = DelegationContext { depth: 4, origin: None };
        let result = spawn_ephemeral_with_ctx(&params, home, "boss", ctx).await;
        assert_eq!(result["isError"], true);
